#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

void inOrder(Node* node) {
    if (node == nullptr) {
        return;
    }
    inOrder(node->left);
    cout << node->data << " ";
    inOrder(node->right);
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    int values[] = {50, 30, 70, 20, 40, 60, 80, 65};
    for (int i = 0; i < 8; i++) {
        root = insert(root, values[i]);
    }
    inOrder(root);
    cout << endl;

    // Case 1: 20 is a leaf.
    Node* leaf = root->left->left;
    root->left->left = nullptr;
    delete leaf;
    inOrder(root);
    cout << endl;

    // Case 2: 60 has one child, 65.
    Node* parent = root->right;
    Node* gone = parent->left;
    parent->left = gone->right;
    delete gone;
    inOrder(root);
    cout << endl;

    // Case 3: the root, 50, has two children.
    Node* succParent = root->right;
    Node* succ = succParent->left;
    root->data = succ->data;
    succParent->left = succ->right;
    delete succ;
    inOrder(root);
    cout << endl;

    destroy(root);
    return 0;
}
